document.addEventListener('DOMContentLoaded',()=>{const data={"Praia do Aventureiro":['praia tranquila · ilha grande','Areia clara, mar aberto e visual preservado para passar o dia.','dia inteiro','barco + trilha curta','Ilha Grande','R$ 80–180'],"Praia Grande":['praia urbana · pôr do sol','Faixa tranquila para caminhar, nadar e assistir ao fim do dia.','2 horas','carro ou táxi','Centro de Angra','gratuito'],"Ilha da Gipóia":['ilha · praias','Um dia entre praias de água transparente e paradas de barco.','dia inteiro','barco','Baía da Ilha Grande','R$ 100–220'],"Ilha Cataguás":['ilha · snorkel','Água rasa e transparente, ótima para nadar e observar peixinhos.','meio período','barco','Baía da Ilha Grande','R$ 80–160'],"Vila do Abraão":['vila · gastronomia','Restaurantes, lojinhas e o ponto de partida para Ilha Grande.','2 horas','barco','Ilha Grande','gratuito'],"Lagoa Azul":['mar calmo · mergulho','Uma das paradas mais procuradas para nadar e fazer snorkel.','meio período','barco','Ilha Grande','R$ 90–180'],"Praia de Lopes Mendes":['praia · trilha','Areia extensa, ondas e uma das paisagens mais marcantes da região.','dia inteiro','barco + trilha','Ilha Grande','R$ 100–220'],"Pico do Papagaio":['trilha · aventura','Vista impressionante para quem gosta de uma trilha desafiadora.','dia inteiro','trilha guiada','Ilha Grande','R$ 80–200']};const apply=()=>{const n=document.querySelector('#title')?.textContent,p=data[n];if(!p)return;document.querySelector('#kind').textContent=p[0];document.querySelector('#desc').textContent=p[1];document.querySelector('#time').textContent=p[2];document.querySelector('#price').textContent=p[3];const name=document.querySelector('#place-name');if(name)name.textContent=n;const copy=document.querySelector('#place-copy');if(copy)copy.textContent=p[1]};const t=document.querySelector('#title');if(t)new MutationObserver(apply).observe(t,{childList:true,characterData:true,subtree:true});apply()});
